pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        vm.assume(from != address(0));
        vm.assume(from.code.length == 0);
        Reverter reverter = new Reverter();
        bool success;
        try c.transfer(from, address(reverter), _tos, v) returns (bool res) {
            success = res;
        } catch {
            success = false;
        }
        assertTrue(success == false);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
